import React from "react";
import tw, { styled } from "twin.macro";

const StepsSection = tw.section`w-full flex flex-col items-center py-16 bg-white`;
const StepsCard = tw.div`bg-white shadow-xl rounded-3xl px-8 py-10 max-w-2xl w-full flex flex-col items-center border border-gray-200`;
const StepsTitle = tw.h2`text-3xl font-extrabold mb-8 text-primary-700 text-center`;
const StepsList = styled.ol`
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  grid-template-rows: repeat(2, auto);
  gap: 2rem;
  width: 100%;
  max-width: 900px;
  margin: 0 auto;
  @media (max-width: 900px) {
    grid-template-columns: 1fr;
    grid-template-rows: none;
  }
`;
const StepItem = styled.li`
  ${tw`flex flex-col items-center text-center bg-white rounded-xl p-6 border-2 border-primary-300 shadow-sm transition hover:shadow-lg`}
`;
const StepIcon = styled.span`
  ${tw`flex-shrink-0 w-12 h-12 flex items-center justify-center rounded-full bg-primary-100 text-primary-600 text-2xl font-bold border-2 border-primary-300 mb-3`}
`;
const StepText = tw.span`text-lg text-gray-800 font-medium`;

const steps = [
  {
    icon: "1",
    text: <>Click the <b>Register to Get Referral Link</b> button above.</>
  },
  {
    icon: "2",
    text: <>Fill in your name and email on the registration page.</>
  },
  {
    icon: "3",
    text: <>If you have a referral link, it will be auto-filled. Otherwise, you can register directly.</>
  },
  {
    icon: "4",
    text: <>After registration, check your email for confirmation and your unique referral link.</>
  },
  {
    icon: "5",
    text: <>Enter your Ticket ID to join the referral programme and unlock sharing options.</>
  },
  {
    icon: "6",
    text: <>Share your referral link with friends and track your referrals on the leaderboard!</>
  },
];

export default function RegistrationSteps() {
  return (
    <StepsSection>
      <StepsCard>
        <StepsTitle>How to Register for BGM Referral</StepsTitle>
        <StepsList>
          {steps.map((step, idx) => (
            <StepItem key={idx}>
              <StepIcon>{step.icon}</StepIcon>
              <StepText>{step.text}</StepText>
            </StepItem>
          ))}
        </StepsList>
      </StepsCard>
    </StepsSection>
  );
}
